import { useState, useEffect, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Plus, Edit, ToggleLeft, ToggleRight, Trash2, Wallet, Printer, Search } from "lucide-react";
import { useFirebaseAuth } from "@/contexts/FirebaseAuthContext";
import { useToast } from "@/hooks/use-toast";
import { WalletFormDialog } from "./WalletFormDialog";
import WalletPrinterDialog from "@/components/WalletPrinterDialog";
import { merchantWalletService } from "@/integrations/firebase/services";
import { walletLimitsService } from "@/utils/walletLimitsService";
import { useNavigate } from "react-router-dom";

interface Wallet {
  id: string;
  provider: string;
  msisdn: string;
  label?: string;
  isActive: boolean;
  dailyLimit: number;
  monthlyLimit: number;
  dailyUsage?: number;
  monthlyUsage?: number;
  transferLimit?: number;
  withdrawLimit?: number;
  transferUsage?: number;
  withdrawUsage?: number;
}

interface WalletsManagementProps {
  showAddButton?: boolean;
  showUsageBars?: boolean;
  showLimitCards?: boolean;
  showEditButton?: boolean;
  onWalletEdit?: (wallet: Wallet) => void;
}

export function WalletsManagement({ showAddButton = true, showUsageBars = true, showLimitCards = true, showEditButton = true, onWalletEdit }: WalletsManagementProps) {
  const [wallets, setWallets] = useState<Wallet[]>([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [isWalletPrinterDialogOpen, setIsWalletPrinterDialogOpen] = useState(false);
  const [editingWallet, setEditingWallet] = useState<Wallet | null>(null);
  const [addButtonVisible, setAddButtonVisible] = useState<boolean>(showAddButton);
  const [confirmDeleteOpen, setConfirmDeleteOpen] = useState(false);
  const [targetDelete, setTargetDelete] = useState<{ id: string; msisdn: string } | null>(null);
  const [selectedWalletIdForPrint, setSelectedWalletIdForPrint] = useState<string | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState("");
  const { user } = useFirebaseAuth();
  const { toast } = useToast();
  const navigate = useNavigate();

  // فلترة المحافظ حسب البحث (رقم، اسم، شركة)
  const filteredWallets = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return wallets;
    const providerName = (p: string) => getProviderDisplayName((p || "").replace(/_/g, " "));
    return wallets.filter((w) => {
      const provider = (w as any).walletProvider || w.provider || "";
      const name = providerName(provider).toLowerCase();
      const msisdn = (w.msisdn || "").replace(/\s/g, "");
      const label = (w.label || "").toLowerCase();
      const queryNorm = q.replace(/\s/g, "");
      return (
        msisdn.includes(queryNorm) ||
        (w.msisdn || "").toLowerCase().includes(q) ||
        label.includes(q) ||
        name.includes(q) ||
        provider.toLowerCase().includes(q)
      );
    });
  }, [wallets, searchQuery]);



  useEffect(() => {
    if (user?.uid) {
      fetchWallets();
    }
  }, [user?.uid]);

  const fetchWallets = async () => {
    try {
      if (!user?.uid) {
        setWallets([]);
        setLoading(false);
        return;
      }
      
      setLoading(true);
      
      // تحميل المحافظ من Firebase مباشرة
      const walletsData = await merchantWalletService.getByMerchantId(user.uid);
      
      // استخدام حقول الاستخدام مباشرة من وثيقة المحفظة
      const walletsWithUsage = walletsData.map((wallet) => ({
        ...wallet,
        dailyUsage: wallet.dailyUsage || 0,
        monthlyUsage: wallet.monthlyUsage || 0,
        transferUsage: wallet.transferUsage || 0,
        withdrawUsage: wallet.withdrawUsage || 0
      }));

      setWallets(walletsWithUsage);
        
    } catch (error) {
      console.error('Error fetching wallets from Firebase:', error);
      toast({
        title: "خطأ",
        description: "فشل في تحميل المحافظ من الخادم. يرجى المحاولة مرة أخرى.",
        variant: "destructive"
      });
      setWallets([]);
    } finally {
      setLoading(false);
    }
  };

  const toggleWalletStatus = async (walletId: string, isActive: boolean) => {
    try {
      await merchantWalletService.update(walletId, { isActive: !isActive });

      // تحديث الحالة المحلية
      const updatedWallets = wallets.map(w => 
        w.id === walletId ? { ...w, isActive: !w.isActive } : w
      );
      setWallets(updatedWallets);

      toast({
        title: "تم التحديث",
        description: `تم ${!isActive ? 'تفعيل' : 'إلغاء تفعيل'} المحفظة بنجاح`
      });
    } catch (error) {
      console.error('Error toggling wallet status:', error);
      toast({
        title: "خطأ",
        description: "فشل في تحديث حالة المحفظة",
        variant: "destructive"
      });
    }
  };

  const deleteWallet = async (walletId: string, msisdn: string) => {
    // فتح نافذة التأكيد الأنيقة بدلاً من window.confirm
    setTargetDelete({ id: walletId, msisdn });
    setConfirmDeleteOpen(true);
  };

  const confirmDelete = async () => {
    if (!targetDelete) return;
    try {
      await merchantWalletService.delete(targetDelete.id);

      // تحديث القائمة المحلية
      const updatedWallets = wallets.filter(w => w.id !== targetDelete.id);
      setWallets(updatedWallets);

      // إعادة الجلب من Firestore لضمان تزامن القائمة مع الخادم
      if (user?.uid) {
        await fetchWallets();
      }

      toast({
        title: "تم الحذف",
        description: `تم حذف المحفظة ${targetDelete.msisdn} بنجاح`,
      });
    } catch (error) {
      console.error('Error deleting wallet:', error);
      toast({
        title: "خطأ",
        description: "فشل في حذف المحفظة",
        variant: "destructive"
      });
    } finally {
      setConfirmDeleteOpen(false);
      setTargetDelete(null);
    }
  };

  const getProgressColor = (usage: number, limit: number) => {
    if (limit === 0) return "bg-muted";
    const percentage = (usage / limit) * 100;
    if (percentage >= 100) return "bg-destructive";
    if (percentage >= 80) return "bg-warning";
    return "bg-success";
  };

  const getProviderColor = (provider: string) => {
    if (!provider) return 'bg-gray-600';
    const p = (provider || "").toLowerCase();
    if (p === 'vodafone_cash' || p === 'vodafone') return 'bg-red-600';
    if (p === 'etisalat_cash' || p === 'etisalat') return 'bg-green-600';
    if (p === 'orange_cash' || p === 'orange') return 'bg-orange-600';
    if (p === 'instapay' || p === 'insta_pay') return 'bg-blue-600';
    if (p === 'we_pay') return 'bg-indigo-600';
    if (p === 'smart_wallet') return 'bg-teal-600';
    if (p === 'access_pay') return 'bg-violet-600';
    return 'bg-gray-600';
  };

  const getProviderBorderColor = (provider: string) => {
    if (!provider) return '#6b7280';
    const p = (provider || "").toLowerCase();
    if (p === 'vodafone_cash' || p === 'vodafone') return '#dc2626';
    if (p === 'etisalat_cash' || p === 'etisalat') return '#16a34a';
    if (p === 'orange_cash' || p === 'orange') return '#ea580c';
    if (p === 'instapay' || p === 'insta_pay') return '#2563eb';
    return '#6b7280';
  };

  const getProviderDisplayName = (provider: string) => {
    if (!provider) return '—';
    const p = (provider || "").toLowerCase();
    if (p === 'vodafone_cash' || p === 'vodafone') return 'فودافون كاش';
    if (p === 'etisalat_cash' || p === 'etisalat') return 'اتصالات كاش';
    if (p === 'orange_cash' || p === 'orange') return 'أورانج كاش';
    if (p === 'instapay' || p === 'insta_pay') return 'انستا باي';
    if (p === 'we_pay') return 'وي باي';
    if (p === 'smart_wallet') return 'سمارت ولت';
    if (p === 'access_pay') return 'أكسس باي';
    return String(provider).replace(/_/g, ' ');
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-64 space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-4 border-primary border-t-transparent"></div>
        <p className="text-muted-foreground animate-pulse">جاري تحميل المحافظ...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">محافظي</h2>
        <div className="flex items-center gap-2">
          {showAddButton && addButtonVisible && (
            <Button onClick={() => {
              setDialogOpen(true);
              setAddButtonVisible(false);
            }} className="btn-primary">
              <Plus className="ml-2 h-4 w-4" />
              إضافة محفظة جديدة
            </Button>
          )}
        </div>
      </div>

      {/* شريط البحث */}
      <div className="relative">
        <Search className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
        <Input
          type="text"
          placeholder="بحث برقم المحفظة أو الاسم أو الشركة..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="pr-10 pl-4 w-full max-w-md"
        />
        {searchQuery.trim() && (
          <span className="text-xs text-muted-foreground block mt-1">
            {filteredWallets.length} من {wallets.length} محفظة
          </span>
        )}
      </div>

      <div className="grid gap-3 max-h-[60vh] overflow-y-auto pr-1">
        {filteredWallets.map((wallet) => {
          const providerKey = (wallet as any).walletProvider || wallet.provider || "";
          const compactView = !showUsageBars && !showLimitCards;
          return (
          <Card
            key={wallet.id}
            className="rounded-2xl border border-gray-200/70 dark:border-gray-800/80 bg-gradient-to-l from-white/90 to-slate-50/90 dark:from-slate-900 dark:to-slate-950 shadow-sm hover:shadow-md transition-all duration-150 overflow-hidden"
            style={{
              borderInlineStartColor: getProviderBorderColor(providerKey),
              borderInlineStartWidth: 4
            }}
          >
            <CardHeader className={compactView ? "py-3 px-4 sm:px-5" : "pb-3 pt-4 px-4 sm:px-5"}>
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="flex items-center gap-3 min-w-0">
                  <div className={`w-2.5 h-2.5 rounded-full shrink-0 ${wallet.isActive ? 'bg-green-500' : 'bg-gray-400'}`} title={wallet.isActive ? 'نشط' : 'غير نشط'} />
                  <Badge className={`${getProviderColor(providerKey)} text-white text-xs font-medium px-2.5 py-0.5 shrink-0`}>
                    {getProviderDisplayName(providerKey)}
                  </Badge>
                  <div className="min-w-0">
                    <CardTitle className="text-base font-semibold text-foreground truncate">{wallet.msisdn}</CardTitle>
                    {wallet.label && (
                      <span className="text-sm text-muted-foreground block truncate">({wallet.label})</span>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-1 shrink-0">
                  {showEditButton && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => {
                        if (onWalletEdit) {
                          onWalletEdit(wallet);
                        }
                      }}
                    >
                      <Edit className="h-4 w-4" />
                    </Button>
                  )}
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => toggleWalletStatus(wallet.id, wallet.isActive)}
                  >
                    {wallet.isActive ? (
                      <ToggleRight className="h-5 w-5 text-success" />
                    ) : (
                      <ToggleLeft className="h-5 w-5 text-muted-foreground" />
                    )}
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => deleteWallet(wallet.id, wallet.msisdn)}
                    className="text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </CardHeader>
            { (showUsageBars || showLimitCards) && (
            <CardContent className="pt-0 px-4 sm:px-5 pb-4">
              <div className="space-y-6">
                {/* أشرطة الحدود الشهرية (مخفية عند showLimitCards = false) */}
                {showLimitCards && (
                <div className="bg-gradient-to-r from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 p-3 rounded-md border border-gray-200 dark:border-gray-700 shadow-sm">
                  <div className="text-xs text-gray-600 dark:text-gray-400 font-medium mb-2 text-center">
                    الحدود الشهرية: {wallet.provider} - {wallet.msisdn}
                  </div>
                  <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 overflow-hidden flex">
                    <div className="w-1/2 bg-red-200 dark:bg-red-900/50 relative">
                      <div
                        className="bg-gradient-to-r from-red-400 to-red-600 h-2 transition-all duration-200 ease-out"
                        style={{ width: `${wallet.withdrawLimit ? Math.min(((wallet.withdrawUsage || 0) / wallet.withdrawLimit) * 100, 100) : 0}%` }}
                      ></div>
                    </div>
                    <div className="w-1/2 bg-blue-200 dark:bg-blue-900/50 relative">
                      <div
                        className="bg-gradient-to-r from-blue-400 to-blue-600 h-2 transition-all duration-200 ease-out"
                        style={{ width: `${wallet.transferLimit ? Math.min(((wallet.transferUsage || 0) / wallet.transferLimit) * 100, 100) : 0}%` }}
                      ></div>
                    </div>
                  </div>
                  <div className="flex justify-between items-center mt-1">
                    <div className="text-xs text-red-600 dark:text-red-400 font-medium">
                      متبقي سحب: {Math.max((wallet.withdrawLimit || 0) - (wallet.withdrawUsage || 0), 0).toLocaleString()} جنيه
                    </div>
                    <div className="text-xs text-blue-600 dark:text-blue-400 font-medium">
                      متبقي تحويل: {Math.max((wallet.transferLimit || 0) - (wallet.transferUsage || 0), 0).toLocaleString('en-US', { maximumFractionDigits: 0 })} جنيه
                    </div>
                  </div>
                </div>
                )}
                {showUsageBars && (
                <div className="bg-muted/30 rounded-lg p-4">
                  <div className="flex justify-between items-center text-sm mb-3">
                    <span className="font-medium text-muted-foreground">الاستخدام اليومي</span>
                    <span className="font-bold">{wallet.dailyUsage?.toLocaleString('en-US', { maximumFractionDigits: 0 })} / {wallet.dailyLimit > 0 ? wallet.dailyLimit.toLocaleString('en-US', { maximumFractionDigits: 0 }) : '∞'} جنيه</span>
                  </div>
                  <Progress
                    value={wallet.dailyLimit > 0 ? Math.min((wallet.dailyUsage || 0) / wallet.dailyLimit * 100, 100) : 0}
                    className={`h-3 ${getProgressColor(wallet.dailyUsage || 0, wallet.dailyLimit)}`}
                  />
                  <div className="text-xs text-muted-foreground mt-1 text-right">
                    {wallet.dailyLimit > 0 ? ((wallet.dailyUsage || 0) / wallet.dailyLimit * 100).toFixed(1) : 0}% مستخدم
                  </div>
                </div>
                )}
                {showUsageBars && (
                <div className="bg-muted/30 rounded-lg p-4">
                  <div className="flex justify-between items-center text-sm mb-3">
                    <span className="font-medium text-muted-foreground">الاستخدام الشهري</span>
                    <span className="font-bold">{wallet.monthlyUsage?.toLocaleString()} / {wallet.monthlyLimit > 0 ? wallet.monthlyLimit.toLocaleString() : '∞'} جنيه</span>
                  </div>
                  <Progress
                    value={wallet.monthlyLimit > 0 ? Math.min((wallet.monthlyUsage || 0) / wallet.monthlyLimit * 100, 100) : 0}
                    className={`h-3 ${getProgressColor(wallet.monthlyUsage || 0, wallet.monthlyLimit)}`}
                  />
                  <div className="text-xs text-muted-foreground mt-1 text-right">
                    {wallet.monthlyLimit > 0 ? ((wallet.monthlyUsage || 0) / wallet.monthlyLimit * 100).toFixed(1) : 0}% مستخدم
                  </div>
                </div>
                )}
                
                {/* حدود التحويل */}
                {showLimitCards && (
            <div className="bg-blue-50 dark:bg-blue-950/30 rounded-lg p-4 border border-blue-200 dark:border-blue-900/50">
                  <div className="flex justify-between items-center text-sm mb-3">
                    <span className="font-medium text-blue-700 dark:text-blue-400">حد التحويل</span>
                    <span className="font-bold text-blue-900 dark:text-blue-200">{wallet.transferUsage?.toLocaleString() || 0} / {wallet.transferLimit?.toLocaleString() || 200000} جنيه</span>
                  </div>
                  <Progress
                    value={wallet.transferLimit ? Math.min((wallet.transferUsage || 0) / wallet.transferLimit * 100, 100) : 0}
                    className="h-3 bg-blue-100 dark:bg-blue-900/30"
                  />
                  <div className="text-xs text-blue-600 dark:text-blue-400 mt-1 text-right">
                    {wallet.transferLimit ? ((wallet.transferUsage || 0) / wallet.transferLimit * 100).toFixed(1) : 0}% مستخدم
                  </div>
                  <div className="text-xs text-blue-700 dark:text-blue-300 mt-1 text-right font-medium">
                    المتبقي: {Math.max((wallet.transferLimit || 0) - (wallet.transferUsage || 0), 0).toLocaleString()} جنيه
                  </div>
                </div>
                )}
                
                {/* حدود السحب */}
                {showLimitCards && (
                <div className="bg-green-50 dark:bg-green-950/30 rounded-lg p-4 border border-green-200 dark:border-green-900/50">
                  <div className="flex justify-between items-center text-sm mb-3">
                    <span className="font-medium text-green-700 dark:text-green-400">حد السحب</span>
                    <span className="font-bold text-green-900 dark:text-green-200">{wallet.withdrawUsage?.toLocaleString() || 0} / {wallet.withdrawLimit?.toLocaleString() || 200000} جنيه</span>
                  </div>
                  <Progress
                    value={wallet.withdrawLimit ? Math.min((wallet.withdrawUsage || 0) / wallet.withdrawLimit * 100, 100) : 0}
                    className="h-3 bg-green-100 dark:bg-green-900/30"
                  />
                  <div className="text-xs text-green-600 dark:text-green-400 mt-1 text-right">
                    {wallet.withdrawLimit ? ((wallet.withdrawUsage || 0) / wallet.withdrawLimit * 100).toFixed(1) : 0}% مستخدم
                  </div>
                  <div className="text-xs text-green-700 dark:text-green-300 mt-1 text-right font-medium">
                    المتبقي: {Math.max((wallet.withdrawLimit || 0) - (wallet.withdrawUsage || 0), 0).toLocaleString()} جنيه
                  </div>
                </div>
                )}
              </div>
            </CardContent>
            )}
          </Card>
          );
        })}

        {filteredWallets.length === 0 && searchQuery.trim() && wallets.length > 0 && (
          <Card className="rounded-xl border border-dashed">
            <CardContent className="text-center py-8">
              <Search className="w-10 h-10 text-muted-foreground mx-auto mb-2" />
              <p className="text-muted-foreground">لا توجد محافظ تطابق البحث</p>
              <Button variant="link" size="sm" className="mt-2" onClick={() => setSearchQuery("")}>
                مسح البحث
              </Button>
            </CardContent>
          </Card>
        )}

        {wallets.length === 0 && (
          <Card className="card-glass">
            <CardContent className="text-center py-16">
              <div className="bg-muted/30 rounded-full w-24 h-24 mx-auto mb-6 flex items-center justify-center">
                <Plus className="w-12 h-12 text-muted-foreground" />
              </div>
              <h3 className="text-xl font-semibold mb-2">لا توجد محافظ</h3>
              <p className="text-muted-foreground mb-6 max-w-md mx-auto">
                ابدأ بإضافة محفظتك الأولى لتتمكن من استقبال المدفوعات من عملائك
              </p>
              {showAddButton && addButtonVisible && (
                <Button 
                  onClick={() => {
                    setDialogOpen(true);
                    setAddButtonVisible(false);
                  }} 
                  size="lg"
                  className="btn-primary px-8"
                >
                  <Plus className="w-5 h-5 ml-2" />
                  إضافة محفظة جديدة
                </Button>
              )}
            </CardContent>
          </Card>
        )}
      </div>

      <WalletFormDialog
        open={dialogOpen}
        onOpenChange={(open) => {
          setDialogOpen(open);
          if (!open) {
            setEditingWallet(null);
            setAddButtonVisible(true);
          }
        }}
        wallet={editingWallet}
        onSuccess={(newWallet) => {
           console.log('onSuccess called with:', newWallet);
           console.log('editingWallet:', editingWallet);
           
           if (newWallet && !editingWallet) {
             console.log('Adding new wallet to list');
             // إضافة المحفظة الجديدة فوراً للقائمة
             setWallets(prevWallets => {
               const updated = [...prevWallets, newWallet];
               console.log('Updated wallets list:', updated);
               return updated;
             });
           } else {
             console.log('Refreshing wallets from Firebase');
             // في حالة التحديث، إعادة تحميل البيانات من Firebase
             fetchWallets();
           }
           setDialogOpen(false);
           setEditingWallet(null);
           setAddButtonVisible(true);
         }}
      />

      {/* نافذة تأكيد الحذف الأنيقة */}
      <Dialog open={confirmDeleteOpen} onOpenChange={setConfirmDeleteOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>تأكيد حذف المحفظة</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <p className="text-sm text-muted-foreground">
              هل أنت متأكد من حذف المحفظة {targetDelete?.msisdn}؟ هذا الإجراء لا يمكن التراجع عنه.
            </p>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setConfirmDeleteOpen(false)}>إلغاء</Button>
              <Button variant="destructive" onClick={confirmDelete}>حذف</Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      <WalletPrinterDialog
        isOpen={isWalletPrinterDialogOpen}
        onClose={() => {
          setIsWalletPrinterDialogOpen(false);
          setSelectedWalletIdForPrint(undefined);
        }}
        wallets={wallets.map(w => ({
          id: w.id,
          name: w.label || w.msisdn,
          phone: w.msisdn,
          walletProvider: w.provider
        }))}
        initialWalletId={selectedWalletIdForPrint}
      />
    </div>
  );
}
